def chain_follow(chain):
    chain_dict = {}
    for token in chain:
        if token not in chain_dict:
            chain_dict[token] = []

    current = chain_dict['gcu']
    chain_dict['gcu'] = []

    while current:
        chain_dict[current].append(current)
        current = chain_dict[current][0]

    return chain_dict['gcu']

